-- Données de départ (mentors, groupes, événements) — mêmes que le mode démo.
-- Exécuté par `npx supabase db reset`.

insert into public.mentors (first_name, last_name, headline, study, city, origin, rating, sessions_count, response_hours, quote, specialties, languages, journey, reviews, available_this_week, avatar_color) values
  ('Adnane', 'Marouane', 'Ingénieur logiciel', 'M2 · Informatique', 'Paris', 'Meknès', 5, 10, 24, '« Mon premier jour à Paris, je pleurais devant la gare. Aujourd’hui, je guide 12 étudiants par mois. C’est ma façon de rendre. »', array['Visa étudiant', 'CAF & APL', 'Banque', 'Sécu sociale']::text[], array['ar', 'fr', 'en']::text[], '[{"year":"2019/2020","title":"Bac Sciences Maths","detail":"Lycée qualifiant à Meknès — mention Très Bien"},{"year":"2020/2023","title":"Licence Informatique","detail":"Arrivée à Paris — Université Paris Sorbonne"},{"year":"2023/2025","title":"Master Génie Logiciel","detail":"Projets d’études et stage de fin d’études à Paris"},{"year":"2026","title":"Ingénieur logiciel","detail":"En CDI dans une tech company à Paris"}]'::jsonb, '[{"author":"Zakaria C.","text":"Adnane m''a tenu la main pour la CAF. Sans lui, j''aurais abandonné.","rating":5},{"author":"Khalil R.","text":"« C’est lui qui m’a aidé à obtenir mon visa, merci Adnane ! »","rating":5}]'::jsonb, true, '#3D78FF'),
  ('Salma', 'Bennani', 'Doctorante en chimie', 'Doctorat · Chimie', 'Lyon', 'Rabat', 4.9, 18, 12, '« J’ai mis 3 mois à trouver un logement. Je veux que ça te prenne 3 jours. »', array['Logement', 'Visale', 'Campus France']::text[], array['ar', 'fr', 'en']::text[], '[{"year":"2018","title":"Bac PC","detail":"Rabat"},{"year":"2018/2023","title":"Licence & Master Chimie","detail":"Université Lyon 1"},{"year":"2023","title":"Doctorat","detail":"Laboratoire de chimie, Lyon"}]'::jsonb, '[{"author":"Imane T.","text":"Super rassurante et très précise sur Visale.","rating":5}]'::jsonb, true, '#A855F7'),
  ('Youssef', 'Haddad', 'Data analyst', 'M1 · Data science', 'Nantes', 'Tunis', 4.8, 7, 6, '« Personne ne m’avait parlé de la CVEC. Maintenant c’est moi qui en parle. »', array['CVEC', 'Job étudiant', 'Banque']::text[], array['ar', 'fr']::text[], '[{"year":"2021","title":"Bac Maths","detail":"Tunis"},{"year":"2021/2024","title":"Licence MIASHS","detail":"Nantes Université"},{"year":"2024","title":"Master Data science","detail":"Nantes, en alternance"}]'::jsonb, '[{"author":"Rania B.","text":"Il répond super vite, même le soir.","rating":5}]'::jsonb, false, '#14B8A6'),
  ('Inès', 'Trabelsi', 'Pharmacienne', 'M2 · Pharmacie', 'Toulouse', 'Sfax', 5, 22, 24, '« La santé en France, c’est simple quand quelqu’un t’explique. »', array['Sécu sociale', 'Mutuelle', 'Carte Vitale']::text[], array['ar', 'fr', 'en']::text[], '[{"year":"2017","title":"Bac Sciences","detail":"Sfax"},{"year":"2017/2023","title":"Études de pharmacie","detail":"Université de Toulouse"}]'::jsonb, '[{"author":"Yasmine K.","text":"Grâce à elle j’ai eu ma carte Vitale en 3 semaines.","rating":5}]'::jsonb, true, '#F43F5E'),
  ('Karim', 'Bouzid', 'Étudiant en commerce', 'M1 · Management', 'Lille', 'Oran', 4.7, 5, 48, '« On est tous passés par là. Demande, il n’y a pas de question bête. »', array['Logement', 'Transport', 'Vie étudiante']::text[], array['ar', 'fr', 'ber']::text[], '[{"year":"2020","title":"Bac Gestion","detail":"Oran"},{"year":"2022/2025","title":"Bachelor Business","detail":"Lille"}]'::jsonb, '[{"author":"Amine D.","text":"Très bons conseils pour la colocation à Lille.","rating":5}]'::jsonb, true, '#6366F1'),
  ('Mouna', 'Alaoui', 'Architecte stagiaire', 'M2 · Architecture', 'Paris', 'Fès', 4.9, 14, 12, '« Paris fait peur au début. Après, tu ne veux plus partir. »', array['Logement', 'Campus France', 'Visa étudiant']::text[], array['ar', 'fr', 'en']::text[], '[{"year":"2019","title":"Bac Sciences Maths","detail":"Fès"},{"year":"2020/2026","title":"École d’architecture","detail":"Paris-Belleville"}]'::jsonb, '[{"author":"Hiba S.","text":"Elle a relu ma lettre Campus France : accepté !","rating":5}]'::jsonb, true, '#F97316');

insert into public.groups (name, city, description, tags, privacy, cover_from, cover_to, emoji, members_count, created_by) values
  ('Étudiants à Paris', 'Paris', 'Bienvenue dans le groupe de référence pour tous les étudiants internationaux et français à Paris !

Ce groupe est un espace d''entraide bienveillant. Pose tes questions sur les démarches (CAF, visa, sécurité sociale), trouve des colocataires, partage tes bons plans sorties, et découvre les meilleurs conseils pour vivre la vraie vie étudiante parisienne.', array['Colocation', 'Bons plans', 'Événements']::text[], 'public', '#F59E0B', '#1E1B4B', '🗼', 100, null),
  ('Étudiants à Nantes', 'Nantes', 'Le QG des étudiants internationaux à Nantes : logement, sorties sur l’île, entraide.', array['Entraide', 'Sorties']::text[], 'public', '#38BDF8', '#065F46', '🐘', 100, null),
  ('Marocains à Paris', 'Paris', 'Ftour, bons plans, démarches et nostalgie de la maison.', array['Communauté', 'Ftour']::text[], 'public', '#DC2626', '#14532D', '🇲🇦', 200, null),
  ('Tech Étudiants Lyon', 'Lyon', 'Stages, alternances et hackathons pour les étudiants tech à Lyon.', array['Stages', 'Tech']::text[], 'public', '#A855F7', '#1E3A8A', '💻', 50, null),
  ('Étudiants à Toulouse', 'Toulouse', 'La ville rose et sa communauté étudiante internationale.', array['Entraide']::text[], 'public', '#FB7185', '#7C2D12', '🌹', 64, null);

insert into public.events (group_id, title, city, place, address, starts_at, description, capacity, price, link, cover_from, cover_to, emoji, attendees_count, created_by) values
  ((select id from public.groups where name = 'Étudiants à Paris' limit 1), 'Soirée Blankka', 'Paris', 'Le Duplex', '2bis Avenue Foch, 75116 Paris', date_trunc('day', now()) + interval '7 days 20 hours 0 minutes', 'Bienvenue dans la maison de culture de référence pour tous les créatifs et passionnés de scène urbaine !

Blankka est un espace de collaboration libre et innovant : musique, arts visuels, rencontres. Partons ensemble d’une page blanche pour façonner et faire vibrer la culture de demain.', 20, 'free', 'https://blankka.com', '#E11D48', '#0F172A', '🎶', 10, null),
  ((select id from public.groups where name = 'Étudiants à Paris' limit 1), 'Paris padel maroc', 'Paris', '4 Padel', 'Boulogne-Billancourt', date_trunc('day', now()) + interval '13 days 18 hours 0 minutes', 'Tournoi de padel amical entre étudiants. Tous niveaux, raquettes prêtées.', 20, 'paid', null, '#B45309', '#1C1917', '🎾', 14, null),
  ((select id from public.groups where name = 'Étudiants à Nantes' limit 1), 'Pique-nique de rentrée', 'Nantes', 'Jardin des Plantes', 'Rue Stanislas Baudry, 44000 Nantes', date_trunc('day', now()) + interval '4 days 13 hours 0 minutes', 'Chacun ramène un plat de chez lui. Le meilleur moyen de rencontrer du monde dès ton arrivée !', 40, 'free', null, '#22C55E', '#14532D', '🧺', 22, null),
  ((select id from public.groups where name = 'Marocains à Paris' limit 1), 'Atelier CAF & APL', 'Paris', 'Maison de l’étudiant', 'Cité internationale, 75014 Paris', date_trunc('day', now()) + interval '10 days 18 hours 30 minutes', 'On remplit ensemble ta demande CAF, ordinateur à disposition. Apporte ton bail et ton RIB.', 30, 'free', null, '#014DF8', '#1F2850', '🧾', 18, null);
